import*as THREE from'three';import{Button,Port,Led,materials}from'../../core/index.js';import{addCadParts}from'../../modeling/cad.js';import{mesh,slab,screw,FACE,portQuaternion}from'../../modeling/parts.js';import{spec}from'./dimensions.js';import data from'./geometry-data.js';import{addStickers}from'./stickers.js';
/** The actual PCB switch is inaccessible through the assembled shell. */
class InspectionSlide extends Button{get interactive(){return this.meta.assemblyInspection===true;}onPointerDown(info){if(this.interactive)super.onPointerDown(info);}onPointerUp(info){if(this.interactive)super.onPointerUp(info);}onPointerCancel(info){if(this.interactive)super.onPointerCancel(info);}}
function board(host){
 const s=new THREE.Shape();s.moveTo(-10.4,-12);s.lineTo(-8.8,-14);s.lineTo(-5.5,-14);s.lineTo(-5.5,-8.2);s.lineTo(5.5,-8.2);s.lineTo(5.5,-14);s.lineTo(8.8,-14);s.lineTo(10.4,-12);s.lineTo(10.4,-7.6);s.lineTo(8,-7.6);s.absarc(8,-4,3.6,-Math.PI/2,-Math.PI*1.5,true);s.lineTo(10.4,-.4);s.lineTo(10.4,12.2);s.lineTo(8.4,14.2);s.lineTo(-8.4,14.2);s.lineTo(-10.4,12.2);s.lineTo(-10.4,-.4);s.lineTo(-8,-.4);s.absarc(-8,-4,3.6,Math.PI/2,-Math.PI/2,true);s.lineTo(-10.4,-7.6);s.closePath();const bore=new THREE.Path();bore.absarc(0,-4,2.05,0,Math.PI*2,false);s.holes.push(bore);
 const pcb=mesh(host.body,new THREE.ExtrudeGeometry(s,{depth:.8,bevelEnabled:false,curveSegments:48}),materials.plastic(0xe7e9de,{roughness:.91}),[0,0,-1.25],'FlashLight fixed PCB with native mounting reliefs and real retaining bore');pcb.userData={role:'physical-pcb',inferred:true};
 // Exact assembled photos show green soldermask immediately around D1. This
 // thin physical finish rests on the PCB; it is neither a hole patch nor a light beam.
 const backing=mesh(host.body,new THREE.BoxGeometry(5.8,4.1,.02),materials.plastic(0x136a3e,{roughness:.9}),[0,8,-.44],'FlashLight real PCB soldermask behind optical window');
 const dark=materials.plastic(0x1e2420,{roughness:.85}),metal=materials.metal(0xb7bbac,{roughness:.45}),ceramic=materials.plastic(0xa49a75,{roughness:.86}),parts=[];
 const part=(name,w,h,d,p,m=dark)=>{const o=slab(host.body,w,h,d,.07,p,m,[],.015);o.name='FlashLight '+name;parts.push(o);return o;};
 const driver=part('U1 AW3641EDNR fixed physical package',3,3,.8,[.6,3,-.45]);for(const sign of[-1,1])for(let i=0;i<5;i++)mesh(host.body,new THREE.BoxGeometry(.5,.28,.15),metal,[.6+sign*1.5,3+(i-2)*.5,-.3],'FlashLight AW3641 fixed soldered lead');
 const shunt=part('R3 R220 current-sense physical resistor',3.2,1.6,.65,[6.1,8.2,-.45]);for(const sign of[-1,1])part('R3 metal end cap',.55,1.65,.7,[6.1+sign*1.55,8.2,-.45],metal);
 for(const[x,y,w,h]of[[3.9,3.4,1.6,.8],[-2,1.3,1.6,.8],[-.5,.2,1.6,.8],[3.2,.3,1.6,.8],[-2.2,3.4,1.6,.8],[-4,.1,.8,1.6]]){part('fixed capacitor/resistor package',w,h,.55,[x,y,-.45],ceramic);for(const sign of[-1,1])part('passive solder termination',.22,h,.6,[x+sign*(w/2-.1),y,-.45],metal);}
 return{pcb,backing,driver,shunt,parts};
}
function selector(host,inspection){const p=spec.mode.position,metal=materials.metal(0xa9afa3,{roughness:.49}),dark=materials.plastic(0x20251f,{roughness:.83});const body=slab(host.body,3.3,6.5,1.25,.12,[p[0],5.65,-.45],dark,[],.025);body.name='FlashLight S1 fixed internal SW-SPDT selector body';const cover=slab(host.body,3.5,6.7,.3,.1,[p[0],5.65,.8],metal,[{w:1.6,h:3.5,r:.1,cx:0,cy:0}],.02);cover.name='FlashLight S1 real slotted metal selector cover';for(const y of[3.65,5.65,7.65])mesh(host.body,new THREE.BoxGeometry(.7,.4,.2),metal,[p[0]+1.8,y,-.32],'FlashLight S1 physical soldered terminal');
 const cap=new THREE.Group();cap.name='FlashLight S1 retained moving thumb';mesh(cap,new THREE.BoxGeometry(1.35,1.4,.8),materials.plastic(0xe2dfb9,{roughness:.65}),[0,0,0],'FlashLight S1 cream moving actuator');for(let i=0;i<3;i++)mesh(cap,new THREE.BoxGeometry(1.25,.13,.1),materials.plastic(0xf0ecd0,{roughness:.75}),[0,(i-1)*.35,.43],'FlashLight S1 thumb grip');const mode=host.add(new InspectionSlide({id:'mode',label:'S1 internal Flash/Torch retained slide',position:p,mesh:cap,axis:spec.mode.axis,travel:spec.mode.travelMm,latching:true,meta:{role:'visual-control',assemblyInspection:inspection,mechanism:'retained-slide',positions:spec.mode.positions,sourceLabels:spec.mode.sourceLabels,detentsMm:[0,spec.mode.travelMm],travelEvidence:spec.mode.travelEvidence,scope:'PCB actuator shape and input intent only. Default closed shell has no pointer access;covers:false exposes it. External position is visual only. No Flash/Torch protocol,automatic pulsing,brightness coupling,GPIO,power,thermal or electrical behavior'}}));if(!inspection)mode.cap.traverse(o=>{delete o.userData.component;});return{body,cover,mode};}
class FixedWhiteLed extends Led{set(state){if(typeof state==='boolean')state={on:state};else if(typeof state==='string'||typeof state==='number')state={on:true};super.set({...state,color:spec.light.color});this.glow.visible=false;}}
function light(host){const p=spec.light.position,base=slab(host.body,2.4,2.2,.65,.08,[p[0],p[1],-.28],materials.plastic(0xe5e4cf,{roughness:.62}),[],.02);base.name='FlashLight D1 real white ceramic LED package';for(const sign of[-1,1])mesh(host.body,new THREE.BoxGeometry(.35,2.25,.2),materials.metal(0xb8b8a8),[p[0]+sign*1.15,p[1],-.32],'FlashLight D1 soldered metal pad');const lens=new THREE.Mesh(new THREE.BoxGeometry(...spec.light.phosphorMm),materials.plastic(0xe8df67,{roughness:.4}));lens.name='FlashLight D1 actual single phosphor optical surface';const led=host.add(new FixedWhiteLed({id:'light',label:'D1 fixed white flash-light appearance',mesh:lens,position:p,color:spec.light.color,radius:.3,glowSize:0,meta:{role:'externally-driven-indicator',fixedColor:'white',part:'D1 single white LED',colorEvidence:spec.light.colorEvidence,scope:'External on/brightness only. Default off. No RGB,beam,scene light,automatic flash pulse,Flash/Torch switch coupling,GPIO,AW3641 protocol,thermal,power or electrical implementation'}}));return{base,led};}
function grove(host){const g=new THREE.Group();g.name='FlashLight real open black HY2.0-4P socket';g.position.fromArray(spec.grove.position);g.quaternion.copy(FACE.bottom);host.body.add(g);const plastic=materials.plastic(spec.grove.color,{roughness:.76}),metal=materials.metal(0xb9b8a5,{roughness:.43}),box=(s,p,n,m=plastic)=>mesh(g,new THREE.BoxGeometry(...s),m,p,'FlashLight Grove '+n),depth=6.3;for(const sign of[-1,1]){box([.65,5.2,depth],[sign*4.675,0,-depth/2],'side wall');box([.7,.6,3.2],[sign*3.85,2.3,-4.7],'guide rail');box([.6,.45,1.2],[sign*3.65,2.375,-1.8],'latch shoulder');}box([8.7,.65,depth],[0,-2.275,-depth/2],'floor');box([8.7,4.55,.65],[0,.325,-depth+.325],'rear wall');box([4.8,.45,2.3],[0,2.375,-4.5],'locking bridge');const contacts=[];for(let i=0;i<4;i++){contacts.push(box([.42,.42,4.5],[(i-1.5)*2,.2,-3.6],`contact ${i+1}`,metal));box([.42,1.4,.42],[(i-1.5)*2,-2.7,-5.8],`tail ${i+1}`,metal);}const port=host.add(new Port({id:'grove',label:'PORT.B · I/O',connector:'grove',position:spec.grove.position,quaternion:portQuaternion('bottom'),hitSize:[10,1,5.2],pins:[{n:1,name:'GND',color:'black'},{n:2,name:'5V',color:'red'},{n:3,name:'S',color:'yellow'},{n:4,name:'NC',color:'white'}],meta:{role:'visual-connector',face:'bottom',scope:'Physical attachment,four contacts and own documented printed pin names only. No voltage,GPIO,PWM,single-wire,electrical or firmware model'}}));return{group:g,contacts,port};}
export function buildFlashLight(host,options={}){const inspection=options.covers===false,parts=addCadParts(host,data,{shell:materials.plastic(0xe8e9e3,{roughness:.79})}),pcb=board(host),mode=selector(host,inspection),lamp=light(host),input=grove(host),fixing=screw(host.body,[0,-4,-3.78],'back',1.35);fixing.name='FlashLight actual fixed recessed hex retaining screw';mesh(host.body,new THREE.CylinderGeometry(.65,.65,6,32).rotateX(Math.PI/2),materials.metal(0xa0a49a),[0,-4,-.7],'FlashLight concealed retaining screw shank');host.flashlightAssembly={parts,pcb,selector:mode,light:lamp,input,fixing,artwork:[]};host.unitStickers=host.flashlightAssembly.artwork=addStickers(host);if(inspection){for(const shell of Object.values(parts))shell.visible=false;for(const panel of host.unitStickers)if(Object.values(parts).includes(panel.parent))panel.visible=false;}}
